package com.example.billingservice.model;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;import java.math.BigDecimal;import java.time.Instant;@Document("subscriptions")public class Subscription{@Id private String id;@Indexed(unique=true)private String orderId;private String customerId,planName,activationId,fulfillmentId;private BigDecimal monthlyAmount;private BillingStatus status;private Instant createdAt,billingStartedAt,nextBillingAt,statusChangedAt;private String statusReason;private Integer billingDay;public Integer getBillingDay(){return billingDay;}public void setBillingDay(Integer v){billingDay=v;}public Instant getStatusChangedAt(){return statusChangedAt;}public void setStatusChangedAt(Instant v){statusChangedAt=v;}public String getStatusReason(){return statusReason;}public void setStatusReason(String v){statusReason=v;}public String getId(){return id;}public String getOrderId(){return orderId;}public void setOrderId(String v){orderId=v;}public String getCustomerId(){return customerId;}public void setCustomerId(String v){customerId=v;}public String getPlanName(){return planName;}public void setPlanName(String v){planName=v;}public String getActivationId(){return activationId;}public void setActivationId(String v){activationId=v;}public String getFulfillmentId(){return fulfillmentId;}public void setFulfillmentId(String v){fulfillmentId=v;}public BigDecimal getMonthlyAmount(){return monthlyAmount;}public void setMonthlyAmount(BigDecimal v){monthlyAmount=v;}public BillingStatus getStatus(){return status;}public void setStatus(BillingStatus v){status=v;}public Instant getCreatedAt(){return createdAt;}public void setCreatedAt(Instant v){createdAt=v;}public Instant getBillingStartedAt(){return billingStartedAt;}public void setBillingStartedAt(Instant v){billingStartedAt=v;}public Instant getNextBillingAt(){return nextBillingAt;}public void setNextBillingAt(Instant v){nextBillingAt=v;}}
